SELECT r.record_id, r.player_id, p.promotion_code, p.promotion_name, r.bonus_amount, r.wagering_required, r.wagering_completed, r.status, r.claimed_at, r.completed_at, r.expired_at FROM t_player_bonus_record r LEFT JOIN t_promotion_rule p ON r.rule_id = p.rule_id WHERE r.deleted = FALSE
AND r.player_id = #{query.playerId}
AND r.status = #{query.status}
ORDER BY r.claimed_at DESC

SELECT COUNT(*)
FROM t_player_bonus_record
WHERE player_id = #{playerId}
      AND rule_id = #{ruleId}
      AND deleted = FALSE
